"""Structural flags of a minimal Sullivan algebra.

These flags record whether a model lies in one of the classes in which
Hilali's conjecture is known by a structural argument, so that the search can
report statistics for the models outside these classes:

* ``pure``: the even generators are closed and ``d(V^odd)`` lies in
  ``Q[V^even]``;
* ``two_stage``: ``d(V)`` lies in the subalgebra generated by the closed
  generators;
* ``coformal``: ``d`` is purely quadratic;
* ``quadratic_part_elliptic``: the quadratic part ``d_2`` of ``d`` defines an
  elliptic algebra;
* ``lowest_part_elliptic``: the part ``d_k`` of lowest word length ``k >= 3``
  defines an elliptic algebra.

A model is flagged ``known_class`` if one of these holds.
"""

from __future__ import annotations

from typing import Dict

from .pure import is_pure
from .sullivan import SullivanAlgebra


def is_two_stage(algebra: SullivanAlgebra) -> bool:
    closed = {i for i in range(algebra.m) if not algebra.dgen[i]}
    return all(
        all(a[j] == 0 for j in range(algebra.m) if j not in closed)
        for v in algebra.dgen
        for a in v
    )


def structural_flags(algebra: SullivanAlgebra) -> Dict[str, object]:
    """Dictionary of flags, see the module documentation."""
    lengths = algebra.word_lengths()
    flags: Dict[str, object] = {
        "pure": is_pure(algebra),
        "two_stage": is_two_stage(algebra),
        "word_lengths": lengths,
        "coformal": lengths in ([], [2]),
        "homogeneous": len(lengths) <= 1,
        "even_closed": all(not algebra.dgen[i] for i in algebra.even_indices),
    }
    flags["quadratic_part_elliptic"] = 2 in lengths and algebra.word_length_part(2).is_elliptic()
    lowest = lengths[0] if lengths else None
    flags["lowest_word_length"] = lowest
    flags["lowest_part_elliptic"] = (
        lowest is not None and lowest >= 3 and algebra.word_length_part(lowest).is_elliptic()
    )
    flags["known_class"] = bool(
        flags["pure"]
        or flags["two_stage"]
        or flags["coformal"]
        or flags["quadratic_part_elliptic"]
        or flags["lowest_part_elliptic"]
    )
    return flags
